"""Apply concise bilingual attack/function chapters without changing module behavior."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
# module | English Usage | Chinese Usage | English setup | Chinese setup | English troubleshooting | Chinese troubleshooting
DATA=r"""
melee|Damages targets inside a marked melee area, with adjustable reach and attack timing.|对标记近战范围内的目标造成伤害，可用于挥拳、踩踏或部件撞击。|Add Melee, mark the attack area and set its damage. Use Always for a first test, then activate with a valid target inside the area.|添加近战攻击，标记攻击范围并设置伤害。首次测试选持续启用，激活后让有效目标进入范围。|Check that the mark belongs to a connected part, the target matches the filter and the trigger is active. Survival cores also need enough Energy.|检查标记是否仍连接、目标是否符合筛选、触发是否成立；生存核心还需足够能量。
flame|Projects a damaging flame stream with particle effects from the marked muzzle, using a cone or fan pattern.|从标记发射口喷出带粒子特效的火焰，对目标造成伤害，支持锥形与扇形喷射。|Mark a muzzle facing open space, choose Cone or Fan and set damage. Use Always, activate and test a target in front.|标记朝向空地的发射口，选择锥形或扇形并设置伤害。使用持续启用，激活后在前方放置目标测试。|If the flame points the wrong way, check the marked face and firing angles. If it does not fire or hurt, check the trigger, target filter and Energy balance.|方向不对时检查标记面和发射角度；不喷火或不扣血时检查触发、目标筛选与能量余额。
arrow|Fires arrows or custom item-model projectiles from a marked muzzle, with straight or target-aimed shots.|从标记发射口射出箭矢或自定义物品外观的投射物，支持直射与目标瞄准。|Add Arrow launcher, mark the muzzle and start with straight aim and Always. Activate, confirm the flight path, then choose a custom appearance if wanted.|添加箭矢发射，标记发射口，先用直线瞄准和持续启用。激活确认轨迹后，再选择需要的物品外观。|Keep the muzzle clear of the machine. Target aim needs an eligible target; custom item size and rotation change appearance, not damage.|保持发射口净空；目标瞄准需要有效目标。自定义物品的大小和旋转只改变外观，不提高伤害。
gun|Fires fast projectiles from a marked muzzle, with custom item appearances and optional impact explosions.|从标记发射口射出高速投射物，可自定义物品外观，并选择命中爆炸。|Mark an outward-facing muzzle, choose straight aim and set damage. Use Always and activate; test a short clear firing lane first.|标记朝外的发射口，选直线瞄准并设置伤害。使用持续启用，先在短距离净空射线上激活测试。|If shots hit the machine, adjust the muzzle start distance. For missing target-aimed shots, check range, target filters and Energy.|打到自身时调整发射口的初始释放位置；目标瞄准不射击时检查搜索范围、目标筛选与能量。
mortar|Launches arcing projectiles toward targets, with optional impact explosions and lingering damage areas.|向目标发射抛物线投射物，可在命中后爆炸或生成关联的持续伤害区域。|Mark a launch face, choose a target type and set damage. Activate with a target in range and enough overhead space for the arc.|标记发射面，选择目标类型并设置伤害。确保目标在范围内、上方留有抛射空间后激活测试。|A target may be in search range but unreachable with the selected launch settings. Check overhead obstacles, launch speed and angle, then Energy.|搜索到目标不代表当前抛射能到达；检查上方障碍、发射速度与角度，再检查能量。
surface_field|Defines a lingering damage-area template that other attacks place at their impact points.|供其他攻击引用的持续伤害区域模板，在命中位置生成区域并持续伤害范围内目标。|Add Persistent area damage and set its shape, damage and duration. Select this template in an attack's impact-area option, then trigger that attack.|添加持续范围伤害，设置形状、伤害和持续时间。在攻击模块的命中后区域选项中引用它，再触发该攻击。|This template does not cast on its own. Check that the attacking module references it and actually lands a hit; also check its target filter and Energy.|模板不会自行释放。检查攻击模块是否引用它、攻击是否真正命中，以及区域的目标筛选和能量。
homing|Deploys a formation of hovering projectiles that charge and launch toward eligible targets.|先部署悬浮投射物阵型，再蓄力并向有效目标发射追踪弹。|Mark the deployment face, choose an item appearance and target type, then set damage. Activate with a target in range and watch deployment before launch.|标记部署面，选择物品外观和目标类型，再设置伤害。让目标进入范围后激活，观察部署与发射过程。|Deployment and launch are separate stages. If it never launches, check the target, line of sight, trigger and Energy; an empty appearance can also hide the model.|部署与发射是两个阶段；一直不发射时检查目标、视线、触发和能量。未选择外观也可能看不到模型。
laser|Fires a laser beam with target tracking and horizontal or vertical sweeping.|发射激光束，可追踪目标并进行水平、垂直扫射。|Mark a muzzle, select a beam style and set length and damage. Use Always and activate; add a sweep angle and speed after the fixed beam works.|标记发射口，选择光束样式并设置长度和伤害。先用持续启用测试固定光束，再添加扫射角度和速度。|Check the muzzle direction and trigger first. Missing custom effects need selected particles; dense particles can leave trails even when the beam itself follows the part.|先检查发射口朝向与触发。自定义特效需选择粒子；粒子会保留自身寿命，可能产生残影。
sphere_blast|Charges a sphere in front of the marked face, then releases one area explosion.|在标记面前方蓄出球体，完成蓄力后造成一次范围爆炸。|Mark a forward-facing origin and set the distance, blast radius and damage. Trigger it in clear space and confirm the charge finishes before the blast.|标记朝前的起点，设置距离、爆炸半径与伤害。在空地触发，确认蓄力结束后发生爆炸。|The sphere stays at its planned cast position. Check charge time, trigger and Energy if no blast occurs; terrain destruction has its own permissions.|球体使用已确定的释放位置；不爆炸时检查蓄力、触发与能量。破坏地形还需相应权限。
slash|Launches traveling arc-shaped slashes, with adjustable size, spread, color and effects.|发射向前飞行的弧形斩击，可调整大小、展开方向、颜色和特效。|Mark an outward-facing muzzle, set damage and a short range, then use Always. Activate in clear space and adjust the arc's orientation after it fires.|标记朝外的发射口，设置伤害和短射程，使用持续启用。在空地激活，确认发射后再调整斩击方向。|Check the marked face and roll angle if the arc looks sideways. Display size alone does not guarantee a hit; check the flight path, target filter and Energy.|斩击方向不对时检查标记面与侧转角度；外观放大不代表必定命中，还需检查轨迹、目标筛选与能量。
ground_strike|Creates ground strikes along configured lines or scattered points, with optional falling-item visuals.|按直线或分布点生成地面打击，可搭配下落物品外观表现巨剑坠落等效果。|Choose a release origin and strike pattern, then set damage and a few strike points. Trigger on open ground and check the warning positions before expanding it.|选择释放起点和打击分布，设置伤害及少量打击点。先在开阔地触发，确认预警位置后再扩大范围。|Strikes need a valid ground surface. Item appearance, size and rotation are visual only; check strike positions, target filters and Energy when damage is missing.|打击需要有效地面；下落物品的外观、大小和旋转仅影响显示。不造成伤害时检查落点、目标筛选与能量。
quake|Sends damaging earthquake waves across the ground in straight, ring or area patterns.|沿地面释放地震波，以直线、圆环或区域形状推进，造成伤害和击飞。|Mark the origin, choose a wave pattern and set range and damage. Activate on flat ground with a target standing in the wave's path.|标记起点，选择波形并设置范围和伤害。先在平地激活，让目标站在波的推进路径上。|Ground rules can exclude airborne targets or interrupt propagation. Check the surface, target filter, trigger and Energy before increasing the range.|接地规则可能排除空中目标或中断推进；先检查地面、目标筛选、触发与能量，再扩大范围。
pull|Pulls nearby targets into a sphere or directional funnel, with direct pulling or stable intake.|用球形范围或定向漏斗牵引目标，可选择直接拉动或更稳定的吸入方式。|For a first test, mark the origin, choose a target type and use a small sphere. Activate near a valid target, then switch to a funnel and adjust its direction if needed.|首次先标记起点、选择目标类型并使用小球形范围。在有效目标附近激活，再按需要切换漏斗并调整方向。|Targets inside the stop distance stop moving by design. Target-position casts use a sphere; a directional funnel needs marked-origin mode.|目标进入停止距离后会停止移动；目标位置释放使用球形，定向漏斗需使用标记起点模式。
freeze|Warns and then freezes eligible players or ordinary mobs inside a circular or rectangular area.|先在圆形或长方形区域内预警，再冻结符合筛选的玩家或普通生物。|Mark an origin, choose a small area and set warning and freeze times. Activate with a valid target inside the marked area.|标记起点，先选小范围，设置预警与冻结时间。激活后让有效目标进入区域测试。|Sable Life creatures are excluded. Check target filters, area height and warning timing; a target-position cast also needs an eligible target in search range.|不会冻结 Sable 生命体。检查目标筛选、范围高度与预警时间；目标位置释放还需搜索范围内存在有效目标。
grab|Captures a nearby player or ordinary mob and holds it at a point that follows the marked part.|抓住附近玩家或普通生物，将其保持在随标记部件移动的位置。|Mark a hand or mouth, set a small capture radius and holding time, then activate near a target. Preview the holding point before using it on a large machine.|标记手部或嘴部，设置较小捕获范围与保持时间，在目标附近激活。用于大型机器前先预览保持点。|Sable Life creatures are excluded. The nearest eligible target must enter capture range; check offsets, trigger and Energy if nothing is caught.|不会抓取 Sable 生命体；最近的有效目标必须进入捕获范围。抓不到时检查偏移、触发与能量。
pulse|Releases an area pulse that damages and knocks back nearby eligible targets.|释放范围冲击脉冲，对附近有效目标造成伤害和击退。|Mark an origin, set a small radius, damage and knockback, then activate near a target. Use the expanding visual if you want a visible shockwave.|标记起点，设置小半径、伤害和击退，在目标附近激活。需要可见冲击波时开启扩散视觉。|A visible wave does not bypass target filtering. Check release position, trigger, interval and Energy if the pulse does not affect a target.|视觉波不会绕过目标筛选；未影响目标时检查释放位置、触发、间隔与能量。
summoned_weapon|Deploys floating item-model weapons in a formation and lets them use a linked attack template.|按阵型部署物品外观的浮空武装，并让武装使用关联攻击模板。|Choose a weapon item, mark a deployment part and select an attack module as its template. Trigger deployment with a valid target nearby.|选择武器物品外观，标记部署部件，并选择一个攻击模块作为模板。在有效目标附近触发部署。|The attack template can stay disabled and unmarked, but must still exist and be allowed. Check weapon lifetime, target selection and Energy if deployed weapons do not attack.|攻击模板可停用且无需标记，但必须仍存在并被允许。武装不攻击时检查寿命、目标选择与能量。
arena|Defines a fixed arena and handles the creature leaving it, with optional return and recorded-structure restoration.|设定固定场地，处理生命体越界，并可归位或按记录恢复结构。|Mark the arena center, set its radius and choose the out-of-bounds response. Record the current structure if using restoration, then activate and test near the boundary.|标记场地中心，设置半径和越界处理。需要恢复结构时记录当前结构，再激活并在边界附近测试。|The creature leaving the arena starts the warning, not a player leaving. Restoration needs a current structure record; also check nearby-player and server permissions.|越界警告由生命体离开场地触发，不是玩家离开。结构恢复需最新记录，并受附近玩家条件及服务器权限影响。
armor|Changes incoming damage for a marked part or the whole creature through signal-controlled rules.|通过信号规则调整标记部件或整个生命体的受伤倍率，可制作弱点与防御阶段。|Choose whole-creature scope or mark a part. Add a negative modifier rule, bind an existing channel and supply the signal it requires, then activate and test damage.|选择全生命体或标记部件，添加负伤害修正规则，绑定已有频道并提供所需信号，再激活测试受伤。|Enabling the module does not bypass its rule conditions. Missing or unbound channels do not activate protection; Survival Heart Cores also need enough Energy.|开启模块不会跳过规则条件；缺失或未绑定的频道不会启用防护。生存生命核心还需足够能量。
linear_movement|Moves connected machine parts by teleporting after a charge or traveling along a route, with optional gravity and step assist.|带动相连机器部件，在蓄力后传送或沿路线行进，可搭配重力与跨步辅助。|Mark the movement direction, choose Travel and a short distance. Bind an internal channel, Preview, activate and supply that channel's signal.|标记移动方向，选择行进与短距离。绑定内部频道，先预览，再激活并向该频道提供信号。|Check the trigger and collision result first. Connected bodies still use conservative bounds, and unloaded destinations block movement; target movement also needs a valid target.|先检查触发与碰撞结果；相连部件仍采用保守包围盒，未加载的目的地区块会阻挡移动。朝目标移动还需有效目标。
auto_facing|Turns the connected creature toward an eligible target, using the marked face as its front.|以标记面作为正面，自动转动相连生命体，使其朝向有效目标。|Mark a clear front face, choose a target type and use Always. Activate with a target in range; enable vertical tracking only if needed.|标记明确的正面，选择目标类型并使用持续启用。让目标进入范围后激活，需要时再开启垂直追踪。|Check target range and filters first, then collision and other motion controllers. A vertical marked face cannot define horizontal-only facing.|先检查目标范围与筛选，再检查碰撞及其他运动控制。水平追踪不能使用朝上或朝下的面作为正面。
signal_turn|Turns connected machine parts from six directional wireless inputs, with analog strength controlling the turn.|根据六个方向的无线输入转动相连机器，信号强度可控制转向幅度。|Mark the front face and bind one turning direction to a channel. Activate and vary that channel's signal, then add the other directions.|标记正面，先为一个转向方向绑定频道。激活并改变该频道的信号，确认后再加入其他方向。|Unbound channels do not turn the machine. Check wireless Master, input source and collisions; another motion controller may currently own rotation.|未绑定的频道不会转动。检查无线总开关、输入来源与碰撞；其他运动控制可能正在占用旋转。
gyroscope|Records a reference posture and smoothly rights connected parts when tilt exceeds the limit.|记录基准姿态，在倾斜超过限制时平滑扶正相连部件。|Mark a fixed main-body part and record its current posture as level. Set a tilt limit and recovery mode, then activate and tip the machine to test.|标记固定主躯干部件，将当前姿态记录为基准。设置倾角限制与回正模式，再激活并使机器倾斜测试。|The tilt limit and righting speed apply to both recovery modes. Check calibration, trigger, collision and rotation locks; this module provides no lift.|倾角限制与回正速度在两种模式下都生效。检查校准、触发、碰撞与旋转锁定；陀螺仪不提供升力。
particles|Creates decorative particle effects in areas, points, lines, rings or spheres.|在区域、点、直线、圆环或球形范围内播放装饰粒子。|Choose a particle and pattern, mark the required point or area and use Always. Activate and adjust the appearance after the first effect appears.|选择粒子与形状，按要求标记点或区域，使用持续启用。激活确认效果后再调整外观。|An empty particle selection is invisible. Check that marks match the chosen pattern; particles are visual and do not cause attack damage.|未选择粒子时不会显示；检查标记是否符合所选形状。该模块只有视觉效果，不造成攻击伤害。
health_bar|Displays a red health bar and optional creature name at a marked point, following the part and facing each viewer.|在标记点显示红色血条与可选名字，随部件移动并面向各自观看者。|Mark a visible point above the machine and choose Always visible for a first test. Activate, then adjust bar size and optional name size.|在机器上方标记可见位置，首次选始终显示。激活后调整血条大小，以及需要显示的名字大小。|Check visibility mode and view distance. Terrain can hide the bar, and a blank core name hides the name text.|检查显示模式与可见距离；地形可以遮挡血条，核心名称为空时不会显示名字。
item_display|Shows an item model at a marked point as decoration, without creating a pickup or damage source.|在标记点显示物品模型作为装饰，不生成可拾取物或伤害来源。|Choose an item, mark its attachment point and set a small display size. Activate or enable the module's always-display option, then adjust rotation.|选择物品，标记附着点并先用较小显示尺寸。激活或开启模块的常驻显示，再调整旋转。|Check the item selection, valid mark and display conditions. This visual model has no collision and cannot be collected.|检查物品选择、标记有效性和显示条件；模型没有碰撞，也不能被拾取。
trigger_sound|Plays a selected sound mix when triggered, with optional marked-block contact detection.|触发时播放选定声音组合，也可通过标记方块的接触来触发音效。|Choose a sound and Preview it. Select trigger playback or mark a contact block, then activate and test that event.|选择声音并试听，选择触发播放或标记接触方块，再激活测试对应事件。|An empty mix is silent. Check contact mode, trigger and replay behavior; hearing range is separate from the contact-detection area.|空声音组合不会播放；检查接触模式、触发与重播方式。听觉范围与接触检测范围是两回事。
sound|Plays creature sounds for approach, hurt and ambient events.|为生命体的靠近、受伤和环境事件播放声音。|Open one event's sound selector, add a sound and Preview it. Activate, then reproduce that event before configuring the others.|打开一个事件的声音选择，添加声音并试听。激活后先触发这个事件，再配置其他事件。|Check the event's detection range and cooldown, not only hearing range. Empty mixes are silent.|检查事件检测范围与冷却，不要只检查听觉范围；空声音组合不会播放。
bgm|Plays creature music with trigger, distance and fade controls.|为生命体播放音乐，并通过触发、距离和渐变控制播放过程。|Choose a music track, Preview it and set a modest hearing range. Activate under the selected start condition and test from nearby.|选择音乐并试听，设置适中的听觉范围。按所选开始条件激活，再从附近测试播放。|Check the start condition and hearing range. Leave or release the creature to verify stopping; multiple nearby music sources can compete.|检查开始条件与听觉范围；离开或解除生命体以确认停止。附近多个音乐来源可能互相竞争。
loot|Assigns loot rewards to a marked part when it detaches, with quantity and chance controls.|为标记部位配置脱落后的战利品，可设置数量与掉落概率。|Mark the loot-bearing part, open its loot editor and copy in an item sample. Set a quantity, then activate and detach that part to test.|标记掉落部位，打开战利品编辑并复制物品样本。设置数量后激活，令该部位脱落测试。|An empty sample or zero quantity produces nothing. Check that the marked part actually detached and that the core permits this module.|空样本或数量为零时不会掉落；检查标记部位是否真正脱落，以及核心是否允许使用该模块。
hover_anchor|Holds a marked point in place while connected parts can move or sway around it.|固定标记点的位置，让相连部件围绕该点运动或摆动。|Mark a stable point on the main body, choose the axes to hold and activate. Add rotation locking only if you want the posture held too.|在主躯干标记稳定位置，选择要固定的轴并激活。需要同时固定姿态时，再开启旋转锁定。|A fixed point is not a lock on every block. Check held axes, offsets and rotation locking if the machine sways or another movement controller waits.|固定一个点不代表锁住每个方块；机器摆动或其他移动控制等待时，检查固定轴、偏移和旋转锁定。
health_adjustment|Heals or damages the creature itself when triggered, for recovery skills or self-damage costs.|触发时对生命体自身回血或扣血，可用于恢复技能或自伤代价。|Set a small positive amount for healing or a negative amount for self-damage. Bind a controlled trigger, activate and send one test signal.|正值用于回血，负值用于自伤；先设置较小数值。绑定可控制的触发，激活后发送一次测试信号。|Healing cannot exceed maximum health. Check trigger timing and cooldown; Survival Heart Cores need Energy for actual healing.|回血不会超过生命上限；检查触发时机与冷却。生存生命核心的实际回血需要能量。
visual_shockwave|Applies screen shake, distortion, zoom or color effects to nearby players for impacts and roars.|向附近玩家呈现震屏、扭曲、缩放或滤色效果，可用于冲击与吼叫反馈。|Mark the effect source, choose one effect and a small strength, then bind a short trigger. Activate and test as a nearby player.|标记效果来源，先选一种效果与较低强度，再绑定短触发。激活后让玩家靠近测试。|Check effect radius, trigger and the player's visual settings. Shake can affect players facing away; other effects retain their own viewing rules.|检查作用半径、触发与玩家视觉设置。震屏可影响背对来源的玩家，其他效果仍遵循各自观看规则。
distortion_trail|Leaves a fading ribbon of air distortion behind a moving or swinging marked part.|在移动或挥动的标记部件后留下逐渐变细、淡出的空气扭曲带。|Mark a moving limb, enable the trail and activate. Move or swing that part, then adjust ribbon size after confirming the trail.|标记会移动的肢体，启用拖尾并激活。让部件移动或挥动，看到拖尾后再调整带状尺寸。|A stationary part may produce no new trail. Check the movement threshold, trigger and client visual settings; this effect causes no damage.|静止部件可能不产生新尾迹；检查移动阈值、触发与客户端视觉设置。该效果不造成伤害。
blueprint_spawn|Spawns a selected server blueprint at a fixed world point or a point following the marked part.|在固定世界点或跟随标记部件的位置生成选定的服务器蓝图。|Select and load a server blueprint, choose its position mode and mark the location. Preview, adjust placement and trigger once.|选择并载入服务器蓝图，选择位置模式并标记位置。先预览调整落点，再触发一次。|Check that the blueprint still exists, placement is allowed and the activation limit is not reached. Activating a spawned core requires a valid core inside the blueprint.|检查蓝图是否仍存在、位置是否允许生成，以及是否达到生成次数上限。生成后激活核心要求蓝图内有有效核心。
entity_hitbox|Adds invisible entity damage receivers that forward hits to the creature's shared health and part defenses.|为生命体添加不可见实体受击框，将命中伤害传给共享生命值和部位防御。|Mark the receiving part, size the box around it and keep Hybrid for a first test. Preview, activate and hit the box with a normal weapon.|标记受击部位，让框覆盖该部位，首次保留 Hybrid。预览确认后激活，用普通武器攻击框测试。|The box is normally invisible outside Preview. Check its active trigger and server box limit; another mod must deliver a supported damage event.|预览之外通常看不到框；检查触发与服务器框数量上限。其他模组还需提供受支持的伤害事件。
block_interaction|Simulates an empty-hand right-click on the nearest supported block in a small area, on the structure or in the world.|在小范围内对最近的受支持方块模拟空手右键，可选择结构交互或世界交互。|Mark a reference face, select the interaction mode and aim the preview box at a door or button. Adjust start distance or offsets, then trigger once.|标记参考面，选择交互模式，让预览框对准门或按钮。调整初始距离或偏移，再触发一次。|The preview box defines the interaction area. Only the nearest supported block is used; containers and crafting screens are skipped.|以预览框作为交互范围，只处理最近的受支持方块；箱子、工作台等打开界面的交互会跳过。
"""

def main():
    entries={}
    for line in DATA.strip().splitlines():
        values=line.split('|');assert len(values)==7,values[0]
        module,en,zh,example_en,example_zh,problem_en,problem_zh=values
        assert module not in entries,module
        entries[module]={'en_us':(en,example_en,problem_en),'zh_cn':(zh,example_zh,problem_zh)}
    catalog_path=ROOT/'src/main/resources/assets/sablelife/manual/catalog.json'
    catalog=json.loads(catalog_path.read_text(encoding='utf-8'))
    chapters=[e for e in catalog['entries'] if e['id'] not in {'sound_timeline','combat_compatibility'}]
    limit=next(e for e in chapters if e['id']=='server_limits');chapters.remove(limit)
    first_module=next(i for i,e in enumerate(chapters) if e.get('module'));chapters.insert(first_module,limit)
    for e in chapters:
        if e.get('module') not in entries:continue
        e['sections']={tab:[f'manual.sablelife.{e["module"]}.brief_{tab}'] for tab in ['usage','example','troubleshooting']}
        e.pop('timeline',None)
    catalog['entries']=chapters;catalog['revision']=max(192,catalog['revision'])
    catalog_path.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    for locale,overlay in [('en_us','scripts/english-manual-review.json'),('zh_cn','scripts/chinese-polish.json')]:
        for rel in [f'src/main/resources/assets/sablelife/lang/{locale}.json',overlay]:
            path=ROOT/rel;strings=json.loads(path.read_text(encoding='utf-8'))
            for module,by_locale in entries.items():
                for tab,value in zip(['usage','example','troubleshooting'],by_locale[locale]):
                    assert '\n' not in value
                    strings[f'manual.sablelife.{module}.brief_{tab}']=value
            path.write_text(json.dumps(strings,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Brief bilingual attack/function chapters:',len(entries))
if __name__=='__main__':main()
